import numpy as np
import pandas as pd

coef_low = np.array([7.30555556, -9.49848485, 8.4534596], dtype=float)
mu12 = float(7.575277777777774)
high_params = np.array([4.75319691, 0.23063293], dtype=float)
use_exp = True

def _mu(speed):
    s = float(speed)
    if s <= 1.2:
        mu = float(np.polyval(coef_low, s))
    else:
        dx = s - 1.2
        if use_exp:
            mu = float(mu12 * np.exp(high_params[0]*dx + high_params[1]*dx*dx))
        else:
            mu = float(mu12 + high_params[0]*dx + high_params[1]*dx*dx)
    return max(mu, 1e-9)

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    speed = float(regime.config.get("speed", 1.0))
    mu = _mu(speed)
    y = rng.poisson(mu, size=n)
    return pd.DataFrame({"unit_id": np.arange(n, dtype=int), "y": y.astype(int)})

